Given an array arr[] of integers and a number x, the task is to find the smallest subarray with a sum strictly greater than x.Examples:Input: x = 51, arr[] = [1, 4, 45, 6, 0, 19]Output: 3Explanation: Minimum length subarray is [4, 45, 6]Input: x = 100, arr[] = [1, 10, 5, 2, 7]Output: 0Explanation: No subarray existTry It YourselfTable of Content[Naive Approach] Using Two Nested Loops - O(n^2) Time and O(1) Space[Better Approach] - Prefix Sum and Binary Search - O(n Log n) Time and O(n) Space[Expected Approach] - Using Sliding Window - O(n) Time and O(1) Space[Naive Approach] Using Two Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to use two nested loops. The outer loop picks a starting element, the inner loop considers all elements (on right side of current start) as ending element. Whenever sum of elements between current start and end becomes greater than x, update the result if current length is smaller than the smallest length so far. 
            C++

    #include <iostream>
using namespace std;

int smallestSubWithSum(int x, vector<int> &arr)
{
    int n = arr.size();
    int res = INT_MAX;

    // Pick every element as starting point
    for (int i = 0; i < n; i++)
    {
        int curr = 0;

        for (int j = i; j < n; j++)
        {
            curr += arr[j];

            if (curr > x)
            {
                res = min(res, j - i + 1);
                break;
            }
        }
    }

    // Return 0 if answer does not exist
    if (res == INT_MAX)
        return 0;

    return res;
}

int main()
{
    vector<int> arr = {1, 4, 45, 6, 10, 19};
    int x = 51;

    cout << smallestSubWithSum(x, arr);

    return 0;
}


