Output3[Expected Approach] - Using Sliding Window - O(n) Time and O(1) SpaceThe idea is to maintain a sliding window, where we keep expanding the window by adding elements until the sum becomes greater than x, then we try to minimize this window by shrinking it from the start while maintaining the sum > x condition. This way, we explore all possible subarrays and keep track of the smallest valid length.
            C++

    #include <iostream>
using namespace std;
int smallestSubWithSum(int x, vector<int> &arr)
{

    int i = 0, j = 0;
    int sum = 0;
    int ans = INT_MAX;

    while (j < arr.size())
    {
        while (j < arr.size() && sum <= x)
        {
            sum += arr[j++];
        }
        if (j == arr.size() && sum <= x)
            break;

        // Minimize window from start while maintaining sum > x
        while (i < j && sum - arr[i] > x)
        {
            sum -= arr[i++];
        }

        ans = min(ans, j - i);

        // Remove current start element and shift window
        sum -= arr[i];
        i++;
    }
    if (ans == INT_MAX)
        return 0;
    return ans;
}

int main()
{
    vector<int> arr = {1, 4, 45, 6, 10, 19};
    int x = 51;

    cout << smallestSubWithSum(x, arr);

    return 0;
}


